<div class="head"><div><h1><?= icon('users') ?> <?= $inactive ? 'Inactive Customers' : 'Customers' ?></h1><p class="muted"><?= $inactive ? 'Deactivated customers keep their history and can be reactivated.' : 'Search by name or meter number — results update live.' ?></p></div>
<div class="acts2"><?= act_link('view', $inactive ? 'Active customers' : 'Inactive customers', url('customers/index', $inactive ? [] : ['show' => 'inactive'])) ?><?= act_link('add', 'Register Customer', url('customers/create')) ?></div></div>
<div class="panel"><?php if (!$inactive): ?><label for="liveSearch" class="sr">Search customers</label><input id="liveSearch" placeholder="Type at least 2 characters…" autocomplete="off" aria-live="polite"><br><br><?php endif; ?>
<div class="tw"><table><thead><tr><th>Name</th><th>Meter No</th><th>Address</th><th>Online</th><th>Actions</th></tr></thead><tbody id="custBody">
<?php foreach ($rows as $c): ?><tr><td><?= e($c['full_name']) ?></td><td><?= e($c['meter_no']) ?></td><td><?= e($c['address']) ?></td><td><?= $c['user_id'] ? 'Yes' : 'No' ?></td><td class="acts2">
<?php if ($inactive): ?><?= act_form('restore', 'Activate', 'customers/activate', ['id' => $c['customer_id']]) ?><?php if ($u['role'] === 'admin'): ?><?= act_form('del', 'Delete', 'customers/delete', ['id' => $c['customer_id']], 'Delete this customer permanently? This only works when there is no reading or bill history.') ?><?php endif; ?>
<?php else: ?><?= act_link('view', 'View', url('customers/show', ['id' => $c['customer_id']])) ?><?= act_link('edit', 'Edit', url('customers/edit', ['id' => $c['customer_id']])) ?><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="5" class="muted">No customers found.</td></tr><?php endif; ?></tbody></table></div></div>
